import path from "node:path";

/**
 * A raw Start Menu application as enumerated by `Get-StartApps`. `appId` is
 * either a UWP application user-model id (contains "!"), a shell virtual item
 * (a `{KnownFolderGUID}\relative\path` string or an `Microsoft.AutoGenerated`
 * id), or a plain path.
 */
export interface StartApp {
  name: string;
  appId: string;
  /** Install location of the owning UWP package, when known. */
  installLocation?: string;
  /** Logo path declared in the AppxManifest (relative to installLocation). */
  logo?: string;
}

/** Known-folder GUIDs that commonly appear in Start Menu shell app ids. */
const KNOWN_FOLDERS: Record<string, { env: string[]; append?: string }> = {
  // System32
  "{1ac14e77-02e7-4e5d-b744-2eb1ae5198b7}": {
    env: ["SystemRoot", "windir"],
    append: "System32",
  },
  // SysWOW64
  "{d65231b0-b2f1-4857-a4ce-a8e7c6ea7d27}": {
    env: ["SystemRoot", "windir"],
    append: "SysWOW64",
  },
  // Windows
  "{f38bf404-1d43-42f2-9305-67de0b28fc23}": {
    env: ["SystemRoot", "windir"],
  },
  // Program Files
  "{6d809377-6af0-444b-8957-a3773f02200e}": {
    env: ["ProgramW6432", "ProgramFiles"],
  },
  // Program Files (x86)
  "{7c5a40ef-a0fb-4bfc-874a-c0f2e0b9fa8e}": {
    env: ["ProgramFiles(x86)", "ProgramFiles"],
  },
  // Common Program Files
  "{f7f1ed05-9f6d-47a2-aaae-29d317c6f066}": {
    env: ["CommonProgramFiles"],
  },
  // LocalAppData
  "{f1b32785-6fba-4fcf-9d55-7b8e7f157091}": {
    env: ["LOCALAPPDATA"],
  },
  // RoamingAppData
  "{3eb685db-65f9-4cf6-a03a-e3ef65729f3d}": {
    env: ["APPDATA"],
  },
  // UserProfile
  "{5e6c858f-0e22-4760-9afe-ea3317b67173}": {
    env: ["USERPROFILE"],
  },
};

/**
 * Parse the JSON produced by `Get-StartApps | ConvertTo-Json`. PowerShell emits
 * a single object (not an array) when exactly one app is returned, and may emit
 * `null`; both are normalised to an array. Entries missing a name or app id are
 * dropped. Property names are matched case-insensitively so either the native
 * `Name`/`AppID` shape or an enriched lower-cased shape is accepted.
 */
export function parseStartApps(json: string): StartApp[] {
  let data: unknown;
  try {
    data = JSON.parse(json);
  } catch {
    return [];
  }
  const rows = Array.isArray(data) ? data : data == null ? [] : [data];
  const result: StartApp[] = [];
  for (const row of rows) {
    if (!row || typeof row !== "object") continue;
    const record = row as Record<string, unknown>;
    const name = pickString(record, ["Name", "name"]);
    const appId = pickString(record, ["AppID", "AppId", "appId", "appid"]);
    if (!name || !appId) continue;
    const installLocation = pickString(record, [
      "InstallLocation",
      "installLocation",
    ]);
    const logo = pickString(record, ["Logo", "logo", "LogoBase", "logoBase"]);
    const entry: StartApp = { name, appId };
    if (installLocation) entry.installLocation = installLocation;
    if (logo) entry.logo = logo;
    result.push(entry);
  }
  return result;
}

function pickString(
  record: Record<string, unknown>,
  keys: string[],
): string | undefined {
  for (const key of keys) {
    const value = record[key];
    if (typeof value === "string" && value.trim()) return value.trim();
  }
  return undefined;
}

/** A UWP application user-model id, for example `Package_hash!AppEntry`. */
export function isUwpAppId(appId: string): boolean {
  return appId.includes("!");
}

/** The shell path form stored on a synthesised Start App entry. */
export function shellAppPath(appId: string): string {
  return `shell:AppsFolder\\${appId}`;
}

/** Whether a path is a synthesised Start App path rather than a file path. */
export function isShellAppPath(filePath: string): boolean {
  return filePath.toLowerCase().startsWith("shell:appsfolder\\");
}

/** Recover the raw AppID from a shell app path; "" when the path is not one. */
export function shellAppTarget(filePath: string): string {
  if (!isShellAppPath(filePath)) return "";
  return filePath.slice("shell:AppsFolder\\".length);
}

/**
 * Resolve a shell app id of the form `{KnownFolderGUID}\relative\path` to a
 * real filesystem path using the supplied environment map. Returns `null` when
 * the id is not a known-folder reference or the folder cannot be resolved.
 */
export function resolveKnownFolderPath(
  appId: string,
  env: Record<string, string | undefined> = process.env,
): string | null {
  const match = /^(\{[0-9a-fA-F-]+\})\\(.+)$/.exec(appId);
  if (!match) return null;
  const guid = match[1].toLowerCase();
  const relative = match[2];
  const folder = KNOWN_FOLDERS[guid];
  if (!folder) return null;
  let base: string | undefined;
  for (const key of folder.env) {
    const value = env[key];
    if (typeof value === "string" && value.trim()) {
      base = value.trim();
      break;
    }
  }
  if (!base) return null;
  const segments = folder.append ? [base, folder.append, relative] : [base, relative];
  return path.win32.normalize(path.win32.join(...segments));
}

interface IconCandidate {
  file: string;
  kind: "targetsize" | "scale" | "plain";
  size: number;
  unplated: boolean;
}

/**
 * Choose the best concrete PNG for a UWP logo from the files that actually
 * exist in the assets directory. `logo` is the manifest-declared base path
 * (for example `Assets\\CalculatorAppList.png`); `files` are the file names in
 * that directory. Contrast variants are skipped; unplated target-size assets
 * nearest 48px are preferred, then scale variants, then a plain `base.png`.
 * Returns the chosen file name, or `null` when nothing matches.
 */
export function pickIconVariant(logo: string, files: string[]): string | null {
  const base = path.win32.basename(logo);
  const dot = base.lastIndexOf(".");
  const stem = (dot >= 0 ? base.slice(0, dot) : base).toLowerCase();
  const ext = (dot >= 0 ? base.slice(dot) : ".png").toLowerCase();

  const candidates: IconCandidate[] = [];
  for (const file of files) {
    const lower = file.toLowerCase();
    if (!lower.startsWith(stem) || !lower.endsWith(ext)) continue;
    // The segment between the stem and the extension, e.g. ".scale-200" or
    // ".targetsize-48_altform-unplated".
    const middle = lower.slice(stem.length, lower.length - ext.length);
    if (middle && !middle.startsWith(".")) continue; // different stem
    if (middle.includes("contrast-")) continue; // high-contrast themes
    const targetMatch = /targetsize-(\d+)/.exec(middle);
    const scaleMatch = /scale-(\d+)/.exec(middle);
    const unplated = middle.includes("unplated");
    if (targetMatch) {
      candidates.push({
        file,
        kind: "targetsize",
        size: Number(targetMatch[1]),
        unplated,
      });
    } else if (scaleMatch) {
      candidates.push({
        file,
        kind: "scale",
        size: Number(scaleMatch[1]),
        unplated,
      });
    } else if (middle === "") {
      candidates.push({ file, kind: "plain", size: 0, unplated: false });
    }
  }
  if (candidates.length === 0) return null;

  candidates.sort((a, b) => rankIcon(b) - rankIcon(a));
  return candidates[0].file;
}

/** Higher is better. Favours unplated targetsize assets nearest 48px. */
function rankIcon(candidate: IconCandidate): number {
  if (candidate.kind === "targetsize") {
    const closeness = 1000 - Math.abs(candidate.size - 48);
    return 100_000 + (candidate.unplated ? 2_000 : 0) + closeness;
  }
  if (candidate.kind === "scale") {
    const closeness = 1000 - Math.abs(candidate.size - 200);
    return 50_000 + closeness;
  }
  return 10_000; // plain base.png
}
